<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $title ?? 'SMPP Control Plane' }}</title><style>:root{--bg:#0b1220;--panel:#111b2e;--muted:#8ea0bb;--text:#edf4ff;--line:#23324d;--accent:#42d3a5;--warn:#f3bd63;--danger:#ff7b8b}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px Inter,system-ui,sans-serif}a{color:inherit;text-decoration:none}.shell{display:flex;min-height:100vh}.side{width:250px;background:#0e1728;border-right:1px solid var(--line);padding:22px 16px;position:fixed;inset:0 auto 0 0}.brand{font-weight:800;font-size:18px;margin:0 10px 26px}.brand span{color:var(--accent)}.section{color:#607594;text-transform:uppercase;font-size:10px;font-weight:800;letter-spacing:1.4px;margin:22px 10px 8px}.nav a{display:block;color:#a9b9d0;padding:10px;border-radius:8px;margin:3px 0}.nav a:hover,.nav a.active{background:#17253e;color:#fff}.main{margin-left:250px;width:calc(100% - 250px);padding:30px 36px}.top{display:flex;align-items:center;justify-content:space-between;margin-bottom:28px}.eyebrow{color:var(--accent);font-size:11px;text-transform:uppercase;letter-spacing:1.5px;font-weight:800}.h1{font-size:28px;font-weight:800;margin:5px 0}.sub,.label{color:var(--muted)}.pill{border:1px solid #285344;background:#103226;color:#8df0cb;padding:7px 10px;border-radius:99px;font-size:12px}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px}.card{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:18px}.label{font-size:12px}.value{font-size:27px;font-weight:800;margin-top:8px}.good{color:var(--accent)}.warn{color:var(--warn)}.bad{color:var(--danger)}.split{display:grid;grid-template-columns:1.4fr 1fr;gap:15px;margin-top:15px}.card h2{font-size:15px;margin:0 0 15px}.row{display:flex;justify-content:space-between;padding:11px 0;border-bottom:1px solid var(--line);color:#b9c7da}.row:last-child{border:0}.status{font-size:11px;padding:4px 7px;border-radius:5px;background:#13382c;color:#88edc9}.modules{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.module{background:#15223a;border:1px solid #253858;padding:13px;border-radius:9px;color:#d3dff0}.module small{display:block;color:var(--muted);margin-top:5px}.button{display:inline-block;background:var(--accent);color:#07131b;padding:9px 14px;border:0;border-radius:8px;font-weight:800;cursor:pointer}.formgrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-bottom:16px}label{display:flex;flex-direction:column;gap:6px;color:var(--muted);font-size:12px}input,select{background:#0b1424;color:var(--text);border:1px solid var(--line);border-radius:7px;padding:10px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:11px 9px;border-bottom:1px solid var(--line);white-space:nowrap}th{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.5px}.tablewrap{overflow:auto}.tag{display:inline-block;padding:4px 7px;border-radius:5px;background:#173a32;color:#8df0cb;font-size:11px}.notice{background:#123a2d;color:#98f2d0;border:1px solid #285844;padding:11px;border-radius:8px;margin-bottom:15px}.error{background:#401d27;color:#ffb1bd;border:1px solid #71303d;padding:11px;border-radius:8px;margin-bottom:15px}.sub a,.card a{color:var(--accent)}code{color:#b5d2ff}@media(max-width:1000px){.grid{grid-template-columns:repeat(2,1fr)}.split{grid-template-columns:1fr}.modules{grid-template-columns:repeat(2,1fr)}}</style></head><body><div class="shell"><aside class="side"><div class="brand"><span>◆</span> SMPP Control Plane</div><nav class="nav"><div class="section">Overview</div><a class="active" href="{{ route('dashboard') }}">Dashboard</a><a href="#">Live Monitor</a><a href="#">SMS Reports</a><div class="section">Operations</div><a href="{{ route('admin.users') }}">Customers & Resellers</a><a href="{{ route('admin.providers') }}">SMPP Providers</a><a href="{{ route('admin.routing') }}">Routing Engine</a><a href="{{ route('admin.rates') }}">Rates</a><a href="{{ route('admin.messages') }}">SMS / CDR Logs</a><div class="section">Finance</div><a href="#">Billing Ledger</a><a href="#">Invoices & Payments</a><a href="#">Profit Reports</a><div class="section">Platform</div><a href="#">API & Webhooks</a><a href="#">Alerts</a><a href="#">Security & Audit</a><a href="#">Settings</a></nav></aside><main class="main">@yield('content')</main></div></body></html>